# ============================================================
# 鴨場產蛋分析互動儀表板
# eggdash/app.R
#
# 前提：已執行 egganalysis0917.R，產生以下 CSV（位於上層目錄）：
#   - daily_summary_all.csv
#   - daily_line_summary.csv
#   - daily_age_weighted.csv
#   - region_egg_data_all.csv
#   - missdate.csv（異常日期，可選）
#   - ind_all.csv（個體資料）
#
# 執行方式：RStudio 開啟此檔案後點 Run App；
#   或在 Console 執行 shiny::runApp("eggdash")
# ============================================================

library(rlang)
library(shiny)
library(dplyr)
library(ggplot2)
library(plotly)
library(DT)
library(readr)
library(stringr)
library(readxl)
library(openxlsx)
library(tidyr)

# ── 常數 ──────────────────────────────────────────────────────
DATA_ROOT  <- if (file.exists("../daily_summary_all.csv")) ".." else "data"
OUTPUT_DIR <- file.path(DATA_ROOT, "output")

`%||%` <- function(a, b) if (!is.null(a) && length(a) > 0) a else b

# 從欄名中猜測最可能對應「籠號」「鴨號」的欄位，猜不到則用 fallback
guess_col <- function(cols, pattern, fallback) {
  hit <- cols[str_detect(cols, pattern)]
  if (length(hit) > 0) hit[1] else fallback
}

# 族群趨勢比較：9 組色盤
TC_COLORS <- c("#1f77b4","#ff7f0e","#2ca02c","#d62728","#9467bd",
               "#8c564b","#e377c2","#7f7f7f","#bcbd22")

# ── 資料載入 ──────────────────────────────────────────────────
safe_csv <- function(path, ...) {
  if (file.exists(path)) {
    tryCatch(
      read_csv(path, show_col_types = FALSE, ...),
      error = function(e) { message("讀取失敗：", path); NULL }
    )
  } else NULL
}

load_data <- function() {
  daily <- safe_csv(file.path(DATA_ROOT, "daily_summary_all.csv")) %||%
           safe_csv(file.path(DATA_ROOT, "daily_summary2025.csv"))
  if (!is.null(daily)) daily <- daily %>% mutate(date = as.Date(date))

  line_daily <- safe_csv(file.path(DATA_ROOT, "daily_line_summary.csv"))
  if (!is.null(line_daily))
    line_daily <- line_daily %>% mutate(date = as.Date(date), gen = as.character(gen))

  age_wt <- safe_csv(file.path(DATA_ROOT, "daily_age_weighted.csv"))
  if (!is.null(age_wt)) age_wt <- age_wt %>% mutate(gen = as.character(gen))

  missdate <- safe_csv(file.path(DATA_ROOT, "missdate.csv"))
  if (!is.null(missdate) && "date" %in% names(missdate))
    missdate <- missdate %>% mutate(date = as.Date(date))

  region_all <- safe_csv(file.path(DATA_ROOT, "region_egg_data_all.csv"))
  if (!is.null(region_all)) region_all <- region_all %>% mutate(date = as.Date(date))

  recent60 <- safe_csv(file.path(DATA_ROOT, "egg_data_recent60.csv"))
  if (!is.null(recent60)) recent60 <- recent60 %>% mutate(date = as.Date(date))

  ind <- tryCatch({
    ind_all_path <- file.path(DATA_ROOT, "ind_all.csv")
    if (file.exists(ind_all_path)) {
      read_csv(ind_all_path, show_col_types = FALSE, na = ".") %>%
        mutate(duck = as.character(duck),
               gen  = as.character(gen),
               sex  = suppressWarnings(as.integer(sex)))
    } else {
      csvs <- list.files(OUTPUT_DIR, pattern = "^L.*g\\d+_\\d{8}\\.csv$", full.names = TRUE)
      if (length(csvs) == 0) return(NULL)
      file_df <- data.frame(
        path = csvs,
        key  = str_remove(basename(csvs), "_\\d{8}\\.csv$"),
        date_key = str_extract(basename(csvs), "\\d{8}"),
        stringsAsFactors = FALSE
      ) %>% group_by(key) %>% slice_max(date_key, n = 1, with_ties = FALSE) %>% ungroup()
      bind_rows(lapply(file_df$path, function(f) {
        tryCatch(
          read_csv(f, show_col_types = FALSE, na = ".") %>%
            mutate(duck = as.character(duck), gen = as.character(gen), sex = as.integer(sex)),
          error = function(e) NULL
        )
      }))
    }
  }, error = function(e) NULL)

  list(daily = daily, line_daily = line_daily, age_wt = age_wt,
       missdate = missdate, region_all = region_all, recent60 = recent60, ind = ind)
}

app_data <- load_data()

# ── 共用 helper ───────────────────────────────────────────────
get_y_config <- function(yaxis, xaxis = "age") {
  col <- switch(yaxis,
    eggs   = if (xaxis == "age") "daily_eggs_total" else "daily_eggs",
    housed = "hen_housed_production",
    day    = "hen_day_production"
  )
  lab    <- switch(yaxis, eggs = "每日產蛋數", housed = "隻舍產蛋率", day = "隻日產蛋率")
  scale  <- if (yaxis != "eggs") 100 else 1
  suffix <- if (yaxis != "eggs") " %" else " 顆"
  list(col = col, lab = lab, scale = scale, suffix = suffix)
}

agg_line_daily <- function(df, ln, gn) {
  df %>%
    filter(line == ln, gen == gn) %>%
    group_by(date) %>%
    summarize(
      daily_eggs   = sum(daily_eggs,   na.rm = TRUE),
      female_count = sum(female_count, na.rm = TRUE),
      female_real  = sum(female_real,  na.rm = TRUE),
      .groups = "drop"
    ) %>%
    mutate(
      hen_housed_production = if_else(female_count > 0, daily_eggs / female_count, NA_real_),
      hen_day_production    = if_else(female_real  > 0, daily_eggs / female_real,  NA_real_)
    )
}


# ── UI ────────────────────────────────────────────────────────
ui <- navbarPage(
  title = "🦆 產蛋分析儀表板",
  theme = NULL,

  # ── 頁面1：全場每日監控 ──────────────────────────────────────
  tabPanel("📊 全場日監控",
    sidebarLayout(
      sidebarPanel(width = 3,
        h4("篩選條件"),
        dateRangeInput("daily_daterange", "日期範圍",
          start  = if (!is.null(app_data$daily)) min(app_data$daily$date, na.rm = TRUE) else Sys.Date() - 365,
          end    = if (!is.null(app_data$daily)) max(app_data$daily$date, na.rm = TRUE) else Sys.Date(),
          format = "yyyy-mm-dd"
        ),
        radioButtons("daily_view", "顯示方式",
          choices  = c("全場加總" = "total", "依區域分色" = "region"),
          selected = "total"
        ),
        hr(),
        actionButton("refresh_btn", "🔄 重新整理資料", class = "btn-sm btn-default"),
        hr(),
        helpText("資料來源：daily_summary_all.csv / region_egg_data_all.csv")
      ),
      mainPanel(width = 9,
        uiOutput("anomaly_banner"),
        fluidRow(
          column(4, wellPanel(h5("近 7 天平均"),  textOutput("avg7"))),
          column(4, wellPanel(h5("近 14 天平均"), textOutput("avg14"))),
          column(4, wellPanel(h5("近 30 天平均"), textOutput("avg30")))
        ),
        plotlyOutput("p_daily", height = "400px"),
        hr(),
        h5("異常日期清單（前後日差 > 200）"),
        DTOutput("tbl_missdate")
      )
    )
  ),

  # ── 頁面2：族群趨勢比較 ──────────────────────────────────────
  tabPanel("📈 族群趨勢比較",
    sidebarLayout(
      sidebarPanel(width = 4,
        h4("全域設定"),
        radioButtons("tc_xaxis", "X 軸",
          choices  = c("週齡（跨批次加權）" = "age", "日期（含各批次）" = "date"),
          selected = "age"
        ),
        radioButtons("tc_yaxis", "Y 軸",
          choices  = c(
            "每日產蛋數"   = "eggs",
            "隻舍產蛋率 %" = "housed",
            "隻日產蛋率 %" = "day"
          ),
          selected = "housed"
        ),
        checkboxInput("tc_smooth", "加平滑線（LOESS）", value = FALSE),
        checkboxInput("tc_facet",  "分面顯示（依排序順序）", value = FALSE),
        hr(),
        h4("選擇族群（最多 9 組）"),
        helpText("品系留空代表不選該組；順序欄影響分面排列。"),
        # 表頭
        fluidRow(
          column(2, tags$b("順序")),
          column(5, tags$b("品系")),
          column(5, tags$b("世代"))
        ),
        # 9 組動態選擇器
        uiOutput("tc_group_selectors")
      ),
      mainPanel(width = 8,
        plotlyOutput("p_tc", height = "650px")
      )
    )
  ),

  # ── 頁面3：個體查詢 ──────────────────────────────────────────
  tabPanel("🔍 個體查詢",
    sidebarLayout(
      sidebarPanel(width = 3,
        h4("篩選條件"),
        selectInput("ind_line", "品系",
          choices  = c("全部" = "ALL",
                       if (!is.null(app_data$ind)) sort(unique(app_data$ind$line)) else character(0)),
          selected = "ALL"
        ),
        selectInput("ind_gen", "世代",
          choices  = c("全部" = "ALL",
                       if (!is.null(app_data$ind)) sort(unique(app_data$ind$gen)) else character(0)),
          selected = "ALL"
        ),
        radioButtons("ind_sex", "性別",
          choices  = c("全部" = "0", "母鴨" = "2", "公鴨" = "1"),
          selected = "2"
        ),
        hr(),
        sliderInput("ind_min_total", "最少總蛋數",
          min = 0, max = 400, value = 0, step = 10
        ),
        sliderInput("ind_min_en40", "最少 EN40（週）",
          min = 0, max = 280, value = 0, step = 10
        ),
        hr(),
        selectInput("ind_hist_var", "分布圖指標",
          choices = c("total_eggs", "EN40", "EN52", "age_first_egg", "EN14")
        ),
        hr(),
        actionButton("download_ind", "⬇ 下載篩選結果 CSV", icon = icon("download")),
        tags$script(HTML('
          Shiny.addCustomMessageHandler("downloadCSV", function(msg) {
            var blob = new Blob([msg.content], {type: "text/csv;charset=utf-8;"});
            var url  = URL.createObjectURL(blob);
            var a    = document.createElement("a");
            a.href = url; a.download = msg.filename;
            document.body.appendChild(a); a.click();
            document.body.removeChild(a); URL.revokeObjectURL(url);
          });
        '))
      ),
      mainPanel(width = 9,
        fluidRow(
          column(7, h5("篩選結果"), DTOutput("tbl_ind")),
          column(5, h5("分布圖"),   plotlyOutput("p_ind_hist", height = "350px"))
        )
      )
    )
  ),

  # ── 頁面4：名單上傳查詢 ──────────────────────────────────────
  tabPanel("📋 名單上傳查詢",
    sidebarLayout(
      sidebarPanel(width = 4,
        h4("上傳名單"),
        fileInput("up_file", "上傳名單（csv / xlsx）", accept = c(".csv", ".xlsx")),
        selectInput("up_line", "品系（用於自動帶入基準日期，不影響比對計算）",
          choices  = c("全部" = "ALL",
                       if (!is.null(app_data$ind)) sort(unique(app_data$ind$line)) else character(0)),
          selected = "ALL"
        ),
        selectInput("up_gen", "世代（用於自動帶入基準日期，不影響比對計算）",
          choices  = c("全部" = "ALL",
                       if (!is.null(app_data$ind)) sort(unique(app_data$ind$gen)) else character(0)),
          selected = "ALL"
        ),
        hr(),
        uiOutput("up_col_selectors"),
        hr(),
        textOutput("up_date_range_hint"),
        textOutput("up_line_date_hint"),
        dateInput("up_anchor_date", "基準（結束）日期",
          value = if (!is.null(app_data$recent60)) max(app_data$recent60$date, na.rm = TRUE) else Sys.Date()
        ),
        numericInput("up_window", "回溯天數（1~14）", value = 7, min = 1, max = 14, step = 1),
        actionButton("up_calc", "計算", class = "btn-primary"),
        hr(),
        downloadButton("up_download", "⬇ 下載結果"),
        hr(),
        helpText("上傳檔需至少包含「籠號」與「鴨號」欄位，欄名不拘，上傳後可自行對應。"),
        helpText("籠號與鴨號需同時與系統資料相符（且為查詢基準日當下現役配對）才能查到產蛋紀錄；只要有任一列不符，系統會直接拒絕並列出有問題的列號/籠號/鴨號，需修正或刪除後重新上傳。"),
        helpText("若上傳檔內有重複的「籠號+鴨號」組合，系統會直接拒絕並顯示錯誤，需修正後重新上傳。")
      ),
      mainPanel(width = 8,
        uiOutput("up_error_banner"),
        uiOutput("up_warning_banner"),
        h5("每日產蛋 0/1 一覽（最後一欄為期間總計；0 以紅字標示）"),
        DTOutput("tbl_up_grid")
      )
    )
  )
)


# ── SERVER ────────────────────────────────────────────────────
server <- function(input, output, session) {

  rv <- reactiveValues(data = app_data)

  observeEvent(input$refresh_btn, {
    rv$data <- load_data()
    showNotification("資料已重新整理", type = "message", duration = 3)
  })

  # ── 頁面1 ──────────────────────────────────────────────────

  output$anomaly_banner <- renderUI({
    miss <- rv$data$missdate
    if (is.null(miss)) return(NULL)
    if (!"problem" %in% names(miss)) {
      return(div(class = "alert alert-info",
                 paste0("ℹ️ missdate.csv 尚無 problem 欄（共 ", nrow(miss),
                        " 筆異常日期）。請在 CSV 中新增 problem 欄並標記後，按「重新整理資料」。")))
    }
    unmarked <- miss %>% filter(is.na(problem) | problem != "*")
    if (nrow(unmarked) == 0) return(NULL)
    div(class = "alert alert-warning",
        paste0("⚠️ 有 ", nrow(unmarked), " 個異常日期尚未在 missdate.csv 標記 problem 欄。"))
  })

  daily_filtered <- reactive({
    d <- rv$data$daily
    if (is.null(d)) return(NULL)
    d %>% filter(date >= input$daily_daterange[1], date <= input$daily_daterange[2])
  })

  recent_avg <- function(days) {
    d <- rv$data$daily
    if (is.null(d)) return(NA)
    d %>% filter(date >= max(date, na.rm = TRUE) - days + 1) %>%
      summarize(avg = mean(total, na.rm = TRUE)) %>% pull(avg) %>% round(1)
  }
  output$avg7  <- renderText({ paste0(recent_avg(7),  " 顆/日") })
  output$avg14 <- renderText({ paste0(recent_avg(14), " 顆/日") })
  output$avg30 <- renderText({ paste0(recent_avg(30), " 顆/日") })

  output$p_daily <- renderPlotly({
    df <- daily_filtered()
    if (is.null(df) || nrow(df) == 0) return(plotly_empty(type = "scatter"))

    if (input$daily_view == "total") {
      plot_ly(df, x = ~date, y = ~total, type = "scatter", mode = "lines",
              text = ~paste0(format(date, "%Y-%m-%d"), "<br>總蛋數：", total),
              hoverinfo = "text", line = list(color = "#2171b5", width = 1.5)) %>%
        plotly::layout(title = list(text = "全場每日總產蛋數"),
                       xaxis = list(title = "日期", tickformat = "%Y-%m", dtick = "M3", tickangle = -45),
                       yaxis = list(title = "總蛋數"), hovermode = "x unified")
    } else {
      ra <- rv$data$region_all
      if (is.null(ra)) return(plotly_empty(type = "scatter"))
      region_df <- ra %>%
        filter(date >= input$daily_daterange[1], date <= input$daily_daterange[2]) %>%
        mutate(tooltip = paste0(format(date, "%Y-%m-%d"), "<br>", region, "：", total_eggs))
      if (nrow(region_df) == 0) return(plotly_empty(type = "scatter"))
      plot_ly(region_df, x = ~date, y = ~total_eggs, color = ~region, colors = "Dark2",
              type = "scatter", mode = "lines",
              text = ~tooltip, hoverinfo = "text", line = list(width = 1.5)) %>%
        plotly::layout(title = list(text = "每日分區產蛋數"),
                       xaxis = list(title = "日期", tickformat = "%m/%d", tickangle = -45),
                       yaxis = list(title = "產蛋數"), hovermode = "x unified",
                       legend = list(title = list(text = "區域")))
    }
  })

  output$tbl_missdate <- renderDT({
    miss <- rv$data$missdate
    if (is.null(miss)) return(datatable(data.frame(提示 = "missdate.csv 不存在")))
    datatable(miss, options = list(pageLength = 10, scrollX = TRUE), rownames = FALSE)
  })


  # ── 頁面2：族群趨勢比較 ──────────────────────────────────────

  # 動態產生 9 組選擇器
  output$tc_group_selectors <- renderUI({
    wt <- rv$data$age_wt
    all_lines <- if (!is.null(wt)) sort(unique(wt$line)) else character(0)
    line_choices <- c("（不選）" = "", all_lines)

    rows <- lapply(1:9, function(i) {
      fluidRow(
        column(2,
          numericInput(paste0("tc_order_", i), label = NULL,
                       value = i, min = 1, max = 9, step = 1, width = "55px")
        ),
        column(5,
          selectInput(paste0("tc_line_", i), label = NULL,
                      choices = line_choices, selected = "", width = "100%")
        ),
        column(5,
          selectInput(paste0("tc_gen_", i), label = NULL,
                      choices = c("（不選）" = ""), selected = "", width = "100%")
        )
      )
    })
    tagList(rows)
  })

  # 各組品系選擇後動態更新世代選項
  for (i in 1:9) {
    local({
      idx     <- i
      line_id <- paste0("tc_line_", idx)
      gen_id  <- paste0("tc_gen_",  idx)
      observeEvent(input[[line_id]], {
        sel <- input[[line_id]]
        wt  <- rv$data$age_wt
        if (is.null(sel) || sel == "" || is.null(wt)) {
          updateSelectInput(session, gen_id, choices = c("（不選）" = ""), selected = "")
          return()
        }
        gens <- wt %>% filter(line == sel) %>% pull(gen) %>% unique() %>% sort()
        updateSelectInput(session, gen_id,
          choices  = c("（不選）" = "", setNames(gens, paste0("第", gens, "代"))),
          selected = ""
        )
      }, ignoreNULL = FALSE)
    })
  }

  # 收集已選組別（依排序號排列）
  tc_groups <- reactive({
    groups <- lapply(1:9, function(i) {
      ln  <- input[[paste0("tc_line_",  i)]]
      gn  <- input[[paste0("tc_gen_",   i)]]
      ord <- input[[paste0("tc_order_", i)]]
      if (is.null(ln) || ln == "" || is.null(gn) || gn == "") return(NULL)
      list(line = ln, gen = gn, order = ord %||% i, slot = i)
    })
    # 過濾未選、依 order 排序（同值則依 slot 遞增）
    valid <- Filter(Negate(is.null), groups)
    if (length(valid) == 0) return(list())
    valid[order(sapply(valid, `[[`, "order"), sapply(valid, `[[`, "slot"))]
  })

  output$p_tc <- renderPlotly({
    groups <- tc_groups()
    wt     <- rv$data$age_wt
    ldate  <- rv$data$line_daily
    yc     <- get_y_config(input$tc_yaxis, input$tc_xaxis)

    if (length(groups) == 0) {
      return(plotly_empty() %>%
        plotly::layout(title = list(text = "請在左側選擇至少一個族群")))
    }

    # 產生各組資料
    df_list <- lapply(seq_along(groups), function(k) {
      g <- groups[[k]]
      if (input$tc_xaxis == "age") {
        if (is.null(wt)) return(NULL)
        df_g <- wt %>% filter(line == g$line, gen == g$gen)
        if (nrow(df_g) == 0) return(NULL)
        df_g %>% mutate(
          x_val   = day_age / 7,
          y_val   = .data[[yc$col]] * yc$scale,
          group   = paste0(g$line, "g", g$gen),
          color_k = k,
          tooltip = paste0(g$line, " 第", g$gen, "代<br>週齡：",
                           round(day_age / 7, 1), "<br>",
                           yc$lab, "：", round(.data[[yc$col]] * yc$scale, 1), yc$suffix)
        )
      } else {
        if (is.null(ldate)) return(NULL)
        df_g <- agg_line_daily(ldate, g$line, g$gen)
        if (nrow(df_g) == 0) return(NULL)
        df_g %>% mutate(
          x_val   = date,
          y_val   = .data[[yc$col]] * yc$scale,
          group   = paste0(g$line, "g", g$gen),
          color_k = k,
          tooltip = paste0(g$line, " 第", g$gen, "代<br>日期：",
                           format(date, "%Y-%m-%d"), "<br>",
                           yc$lab, "：", round(.data[[yc$col]] * yc$scale, 1), yc$suffix)
        )
      }
    })
    df_list <- Filter(Negate(is.null), df_list)
    if (length(df_list) == 0) {
      return(plotly_empty() %>% plotly::layout(title = list(text = "所選族群無資料")))
    }

    x_title <- if (input$tc_xaxis == "age") "週齡 (週)" else "日期"

    if (input$tc_facet) {
      # 分面模式：ggplot2 + facet_wrap，依排序後順序排列格子
      group_order <- sapply(df_list, function(d) d$group[1])
      df_all <- bind_rows(df_list) %>%
        mutate(group = factor(group, levels = group_order))

      p <- ggplot(df_all, aes(x = x_val, y = y_val,
                              color = group, group = group, text = tooltip)) +
        geom_line(alpha = 0.75, linewidth = 0.8) +
        scale_color_manual(values = setNames(TC_COLORS[seq_along(group_order)], group_order)) +
        facet_wrap(~ group, ncol = 3, scales = "free_x") +
        labs(title = paste0("族群趨勢比較：", yc$lab),
             x = x_title, y = paste0(yc$lab, yc$suffix), color = "品系‧世代") +
        theme_bw() +
        theme(axis.text.x = element_text(angle = 45, hjust = 1))

      if (input$tc_smooth) {
        p <- p + geom_smooth(aes(group = group), method = "loess",
                             se = FALSE, linewidth = 0.5, alpha = 0.6)
      }
      ggplotly(p, tooltip = "text")

    } else {
      # 疊圖模式：plot_ly
      pl <- plot_ly()
      for (k in seq_along(df_list)) {
        df_g <- df_list[[k]]
        gname <- df_g$group[1]
        col   <- TC_COLORS[k]
        pl <- pl %>%
          add_trace(data = df_g, x = ~x_val, y = ~y_val, name = gname,
                    type = "scatter", mode = "lines",
                    line = list(color = col, width = 1.2),
                    text = ~tooltip, hoverinfo = "text")
        if (input$tc_smooth) {
          lo <- tryCatch(loess(y_val ~ as.numeric(x_val), data = df_g, span = 0.3), error = function(e) NULL)
          if (!is.null(lo)) {
            df_g$y_smooth <- predict(lo, as.numeric(df_g$x_val))
            pl <- pl %>%
              add_trace(data = df_g, x = ~x_val, y = ~y_smooth,
                        name = paste0(gname, "（平滑）"),
                        type = "scatter", mode = "lines",
                        line = list(color = col, width = 2, dash = "dash"),
                        hoverinfo = "skip", showlegend = FALSE)
          }
        }
      }
      pl %>% plotly::layout(
        title     = list(text = paste0("族群趨勢比較：", yc$lab)),
        xaxis     = list(title = x_title),
        yaxis     = list(title = paste0(yc$lab, yc$suffix)),
        hovermode = "x unified",
        legend    = list(title = list(text = "品系‧世代"))
      )
    }
  })


  # ── 頁面3 ──────────────────────────────────────────────────

  ind_filtered <- reactive({
    df <- rv$data$ind
    if (is.null(df)) return(NULL)
    if (input$ind_line != "ALL") df <- df %>% filter(line == input$ind_line)
    if (input$ind_gen  != "ALL") df <- df %>% filter(gen  == input$ind_gen)
    if (input$ind_sex  != "0")   df <- df %>% filter(sex  == as.integer(input$ind_sex))
    if (!is.null(df$total_eggs)) df <- df %>% filter(is.na(total_eggs) | total_eggs >= input$ind_min_total)
    if (!is.null(df$EN40))       df <- df %>% filter(is.na(EN40) | EN40 >= input$ind_min_en40)
    df
  })

  observe({
    df <- rv$data$ind
    if (is.null(df)) return()
    updateSelectInput(session, "ind_line", choices = c("全部" = "ALL", sort(unique(df$line))))
  })
  observe({
    df <- rv$data$ind
    if (is.null(df)) return()
    gens <- if (input$ind_line == "ALL") sort(unique(df$gen)) else sort(unique(df$gen[df$line == input$ind_line]))
    updateSelectInput(session, "ind_gen", choices = c("全部" = "ALL", gens))
  })

  IND_COLS <- c("duck", "cage", "line", "gen", "hatch", "sex",
                "birthday", "firstegg", "total_eggs",
                "EN40", "EN52", "EN14", "age_first_egg", "last_age")

  output$tbl_ind <- renderDT({
    df <- ind_filtered()
    if (is.null(df)) return(datatable(data.frame(提示 = "無個體資料或篩選結果為空")))
    show_cols <- intersect(IND_COLS, names(df))
    datatable(
      df %>% select(all_of(show_cols)),
      filter = "top", rownames = FALSE,
      options = list(pageLength = 15, scrollX = TRUE,
                     columnDefs = list(list(className = "dt-right",
                       targets = which(show_cols %in%
                         c("total_eggs","EN40","EN52","EN14","age_first_egg","last_age")) - 1)))
    ) %>% formatRound(intersect(c("EN40","EN52"), show_cols), digits = 0)
  })

  output$p_ind_hist <- renderPlotly({
    df <- ind_filtered()
    if (is.null(df)) return(plotly_empty())
    var <- input$ind_hist_var
    if (!var %in% names(df)) return(plotly_empty())
    df2 <- df %>% select(val = !!sym(var)) %>% filter(!is.na(val))
    if (nrow(df2) == 0) return(plotly_empty())
    p <- ggplot(df2, aes(x = val)) +
      geom_histogram(fill = "#2171b5", color = "white", bins = 20) +
      labs(title = paste0(var, " 分布"), x = var, y = "頻次") +
      theme_bw()
    ggplotly(p)
  })

  observeEvent(input$download_ind, {
    df <- ind_filtered()
    if (!is.null(df) && nrow(df) > 0) {
      csv_text <- paste(capture.output(write.csv(df, stdout(), row.names = FALSE, na = ".")), collapse = "\n")
      session$sendCustomMessage("downloadCSV", list(
        content = csv_text, filename = paste0("ind_export_", Sys.Date(), ".csv")
      ))
    }
  })


  # ── 頁面4：名單上傳查詢 ──────────────────────────────────────

  up_raw <- reactive({
    req(input$up_file)
    ext <- tolower(tools::file_ext(input$up_file$name))
    df <- tryCatch({
      if (ext == "csv") {
        read_csv(input$up_file$datapath, show_col_types = FALSE)
      } else if (ext == "xlsx") {
        readxl::read_excel(input$up_file$datapath)
      } else {
        NULL
      }
    }, error = function(e) NULL)
    if (!is.null(df)) df <- as.data.frame(df, stringsAsFactors = FALSE)
    df
  })

  output$up_col_selectors <- renderUI({
    df <- up_raw()
    if (is.null(df)) return(helpText("請先上傳檔案。"))
    cols <- names(df)
    tagList(
      selectInput("up_cage_col", "對應「籠號」欄位（例：A101）", choices = cols,
                  selected = guess_col(cols, "籠|cage", cols[1])),
      selectInput("up_duck_col", "對應「鴨號」欄位（例：200001，6碼）", choices = cols,
                  selected = guess_col(cols, "鴨|duck|腳", cols[min(2, length(cols))]))
    )
  })

  output$up_date_range_hint <- renderText({
    rc <- rv$data$recent60
    if (is.null(rc) || nrow(rc) == 0)
      return("目前無可查詢的逐日產蛋資料（egg_data_recent60.csv 不存在或為空）。")
    paste0("整體資料可查詢範圍：", format(min(rc$date, na.rm = TRUE), "%Y-%m-%d"),
           " ~ ", format(max(rc$date, na.rm = TRUE), "%Y-%m-%d"))
  })

  # 依所選品系/世代，算出該範圍籠位在 recent60 中的最後資料日期
  up_line_last_date <- reactive({
    rc  <- rv$data$recent60
    ped <- rv$data$ind
    if (is.null(rc) || nrow(rc) == 0 || is.null(ped)) return(NULL)

    df <- ped
    if (input$up_line != "ALL") df <- df %>% filter(line == input$up_line)
    if (input$up_gen  != "ALL") df <- df %>% filter(gen  == input$up_gen)
    cages <- unique(as.character(df$cage))
    if (length(cages) == 0) return(NULL)

    d <- suppressWarnings(max(rc$date[rc$cage %in% cages], na.rm = TRUE))
    if (!is.finite(d)) return(NULL)
    as.Date(d, origin = "1970-01-01")
  })

  observeEvent(list(input$up_line, input$up_gen), {
    d <- up_line_last_date()
    if (!is.null(d)) updateDateInput(session, "up_anchor_date", value = d)
  }, ignoreInit = TRUE)

  output$up_line_date_hint <- renderText({
    d <- up_line_last_date()
    if (is.null(d)) return("所選品系/世代在目前保留範圍內查無資料。")
    paste0("所選品系/世代最後資料日期：", format(d, "%Y-%m-%d"))
  })

  up_result <- eventReactive(input$up_calc, {
    df <- up_raw()
    rc <- rv$data$recent60
    ped <- rv$data$ind

    req(df)
    cage_col <- input$up_cage_col
    duck_col <- input$up_duck_col
    req(cage_col, duck_col)

    df2 <- df
    df2$.cage_key <- as.character(df2[[cage_col]])
    df2$.duck_key <- as.character(df2[[duck_col]])

    # 1) 上傳檔內「籠號+鴨號」重複 → 整份拒絕
    dup_mask <- duplicated(df2[c(".cage_key", ".duck_key")]) |
                duplicated(df2[c(".cage_key", ".duck_key")], fromLast = TRUE)
    if (any(dup_mask)) {
      dup_rows <- which(dup_mask)
      return(list(error = paste0(
        "❌ 上傳檔案內有重複的「籠號+鴨號」組合，列號：",
        paste(dup_rows, collapse = ", "), "。請修正後重新上傳。"
      )))
    }

    if (is.null(rc) || nrow(rc) == 0) {
      return(list(error = "❌ 目前無可查詢的逐日產蛋資料（egg_data_recent60.csv 不存在或為空）。"))
    }
    if (is.null(ped)) {
      return(list(error = "❌ 系統個體資料（ind_all.csv）不存在，無法比對籠號/鴨號。"))
    }

    anchor  <- input$up_anchor_date
    n_days  <- max(1, min(14, round(input$up_window)))
    start_d <- anchor - (n_days - 1)
    col_name <- paste0("EN", n_days)

    rng_min <- min(rc$date, na.rm = TRUE)
    rng_max <- max(rc$date, na.rm = TRUE)
    out_note <- if (start_d < rng_min || anchor > rng_max) {
      paste0("⚠️ 選取的日期區間（", start_d, " ~ ", anchor,
             "）超出目前資料保留範圍（", rng_min, " ~ ", rng_max, "），部分天數可能無資料。")
    } else NULL

    # 2) 籠號+鴨號需同時與系統資料（ind_all）相符，且在查詢基準日當下仍是現役配對才算匹配
    #    （避免已退場個體的舊籠號+鴨號組合，誤配到現在佔用同籠位的個體身上，見
    #    名單上傳查詢_跨世代籠位誤配問題.md）
    ped_pairs <- ped %>%
      filter(as.Date(start_date) <= anchor,
             is.na(end_date) | as.Date(end_date) >= anchor) %>%
      transmute(cage = as.character(cage), duck = as.character(duck)) %>%
      distinct()

    df2 <- df2 %>%
      left_join(ped_pairs %>% mutate(.matched = TRUE),
                by = c(".cage_key" = "cage", ".duck_key" = "duck"))
    df2$.matched[is.na(df2$.matched)] <- FALSE

    # 2b) 任一列籠號+鴨號與系統資料不符 → 整份拒絕（需同時相符，且為查詢基準日當下現役配對）
    if (any(!df2$.matched)) {
      bad_idx <- which(!df2$.matched)
      bad_desc <- paste0(
        "第", bad_idx, "列（籠號=", df2$.cage_key[bad_idx],
        "，鴨號=", df2$.duck_key[bad_idx], "）"
      )
      return(list(error = paste0(
        "❌ 以下列的籠號/鴨號與系統資料不符（需同時相符，且為查詢基準日當下現役配對），",
        "請修正或刪除後重新上傳：", paste(bad_desc, collapse = "；")
      )))
    }

    # 3) 依籠號加總回溯天數內的產蛋數（邏輯同 EN14／舊版特殊9）
    win_data <- rc %>% filter(date >= start_d, date <= anchor)
    cage_sum <- win_data %>% group_by(cage) %>%
      summarise(.en = sum(egg, na.rm = TRUE), .groups = "drop")

    df2 <- df2 %>% left_join(cage_sum, by = c(".cage_key" = "cage"))
    df2[[col_name]] <- ifelse(is.na(df2$.en), "0", as.character(df2$.en))

    warn_text <- paste(out_note, collapse = " ")

    helper_cols <- c(".cage_key", ".duck_key", ".matched", ".en")
    keep_cols   <- setdiff(names(df2), helper_cols)
    result_df   <- df2[, keep_cols]

    # 逐日 0/1 寬表：此時所有上傳列皆已通過籠號/鴨號比對
    all_keys <- df2 %>% distinct(.cage_key, .duck_key)
    grid_long <- win_data %>% filter(cage %in% all_keys$.cage_key)
    grid_wide <- if (nrow(grid_long) > 0) {
      grid_long %>%
        mutate(date_chr = format(date, "%Y-%m-%d")) %>%
        select(cage, date_chr, egg) %>%
        pivot_wider(id_cols = cage, names_from = date_chr, values_from = egg, values_fill = 0)
    } else {
      data.frame(cage = character(0))
    }
    date_cols <- setdiff(names(grid_wide), "cage")

    grid_df <- all_keys %>%
      rename(cage = .cage_key, duck = .duck_key) %>%
      left_join(grid_wide, by = "cage")

    period_sum <- if (length(date_cols) > 0) {
      rowSums(grid_df[date_cols], na.rm = TRUE)
    } else {
      rep(0, nrow(grid_df))
    }
    grid_df$期間總計 <- as.character(period_sum)

    list(
      error    = NULL,
      warning  = if (nchar(warn_text) > 0) warn_text else NULL,
      result   = result_df,
      grid     = grid_df,
      date_cols = date_cols,
      orig_ext = tools::file_ext(input$up_file$name)
    )
  })

  output$up_error_banner <- renderUI({
    if (is.null(input$up_calc) || input$up_calc == 0) return(NULL)
    r <- up_result()
    if (!is.null(r$error)) div(class = "alert alert-danger", r$error) else NULL
  })

  output$up_warning_banner <- renderUI({
    if (is.null(input$up_calc) || input$up_calc == 0) return(NULL)
    r <- up_result()
    if (is.null(r$error) && !is.null(r$warning)) div(class = "alert alert-warning", r$warning) else NULL
  })

  output$tbl_up_grid <- renderDT({
    if (is.null(input$up_calc) || input$up_calc == 0)
      return(datatable(data.frame(提示 = "請上傳檔案、對應欄位後點擊「計算」"), rownames = FALSE))
    r <- up_result()
    if (!is.null(r$error) || is.null(r$grid) || nrow(r$grid) == 0)
      return(datatable(data.frame(提示 = "無可顯示的逐日資料"), rownames = FALSE))
    dt <- datatable(r$grid, rownames = FALSE, options = list(pageLength = 15, scrollX = TRUE))
    if (length(r$date_cols) > 0) {
      dt <- dt %>% formatStyle(r$date_cols, color = styleEqual(0, "red"))
    }
    dt
  })

  output$up_download <- downloadHandler(
    filename = function() {
      orig_name <- input$up_file$name %||% "result.csv"
      base <- tools::file_path_sans_ext(orig_name)
      ext  <- tools::file_ext(orig_name)
      anchor  <- input$up_anchor_date
      n_days  <- max(1, min(14, round(input$up_window)))
      start_d <- anchor - (n_days - 1)
      date_tag <- paste0(format(start_d, "%Y%m%d"), "-", format(anchor, "%Y%m%d"))
      paste0(base, "_result_", date_tag, ".", if (ext == "") "csv" else ext)
    },
    content = function(file) {
      r <- tryCatch(up_result(), error = function(e) NULL)
      if (is.null(r) || !is.null(r$error) || is.null(r$result)) {
        write.csv(data.frame(訊息 = "尚無可下載的結果，請先上傳檔案並點擊計算。"), file, row.names = FALSE)
        return(invisible())
      }
      if (tolower(r$orig_ext) == "xlsx") {
        openxlsx::write.xlsx(r$result, file)
      } else {
        write.csv(r$result, file, row.names = FALSE, na = ".")
      }
    }
  )

}

